import structfilepath=r'C:\Users\michael.cheng\Documents\Zemax\POP\BEAMFILES\Basic Propagation_0004.ZBF'bfile=open(filepath, 'rb')Version = int.from_bytes(bfile.read(4), byteorder='little')Nx = int.from_bytes(bfile.read(4), byteorder='little')Ny = int.from_bytes(bfile.read(4), byteorder='little')IsPol = int.from_bytes(bfile.read(4), byteorder='little')Units = int.from_bytes(bfile.read(4), byteorder='little')Unused = int.from_bytes(bfile.read(16), byteorder='little')Xspacing = struct.unpack('d', bfile.read(8))[0]Yspacing = struct.unpack('d', bfile.read(8))[0]X_ZPos = struct.unpack('d', bfile.read(8))[0]X_ZR = struct.unpack('d', bfile.read(8))[0]X_W0 = struct.unpack('d', bfile.read(8))[0]Y_ZPos = struct.unpack('d', bfile.read(8))[0]Y_ZR = struct.unpack('d', bfile.read(8))[0]Y_W0 = struct.unpack('d', bfile.read(8))[0]Wave = struct.unpack('d', bfile.read(8))[0]Indx = struct.unpack('d', bfile.read(8))[0]Rec_Eff = struct.unpack('d', bfile.read(8))[0]Sys_Eff = struct.unpack('d', bfile.read(8))[0]print(filepath)print('Version =   ' + str(Version))print('Nx =        ' + str(Nx))print('Ny =        ' + str(Ny))print('IsPol =     ' + str(IsPol))print('Xspacing =  ' + str(Xspacing))print('Yspacing =  ' + str(Yspacing))print('XWidth =    ' + str(Xspacing*(Nx-1)))print('YWidth =    ' + str(Yspacing*(Ny-1)))print('')print('X_ZPos =    ' + str(X_ZPos))print('X_ZR =      ' + str(X_ZR))print('X_W0 =      ' + str(X_W0))print('Y_ZPos =    ' + str(Y_ZPos))print('Y_ZR =      ' + str(Y_ZR))print('Y_W0 =      ' + str(Y_W0))print('Wave =      ' + str(Wave))print('Indx =      ' + str(Indx))print('Rec_Eff =   ' + str(Rec_Eff))print('Sys_Eff =   ' + str(Sys_Eff))